// Original Valus instruction mapped to the 2026–27 HOSA event blueprints.
// Practice assessments are educational and are not official HOSA questions.
import { EVENT_DETAILS } from './event-details.js';

export const COURSES_ONE = {};
// Compact authoring helper keeps every lesson's concepts, case and assessment distinct.
function S(title, concepts, scenario, explanation, questions, response, criteria, model) {
  return {title,points:concepts,case:scenario,explain:explanation,questions,frq:response,criteria,model};
}
const slug = value => value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const Q = (prompt, correct, wrong, explanation) => ({prompt,options:[correct,...wrong],answer:0,explanation});
function course(name, units) {
  const source = {title:'Official HOSA 2026–27 event guidelines',url:EVENT_DETAILS[name].source};
  COURSES_ONE[name] = {units:units.map(([title,lessons])=>({title,lessons:lessons.map((l)=>({
    id:slug(name+' '+l.title),minutes:18,objectives:l.points.map(p=>p[0]),
    sections:l.points.map(p=>({title:p[0],paragraphs:p[1].split('~')})),
    diagram:{title:l.diagramTitle||'Connect the concepts',nodes:l.points.map(p=>({label:p[0],detail:p[2]||p[1].split('.')[0]+'.'}))},
    example:{prompt:l.case,explanation:l.explain},
    mcqs:l.questions,
    frq:{prompt:l.frq,rubric:l.criteria.map(([label,keywords])=>({label,keywords})),modelAnswer:l.model},
    sources:[source,...(l.sources||[])],title:l.title
  }))}))};
}

course('Behavioral Health',[
['The mind: biology, learning and memory',[
{title:'From neurons to perception',points:[
['Signals and systems','Neurons communicate through electrical changes along their membranes and chemical signaling across synapses. Dendrites generally receive input, the cell body integrates it, and the axon carries an action potential toward terminals. Neurotransmitters interact with receptors; their effects depend on receptor type and the receiving circuit. A single chemical does not explain an entire emotion or diagnosis. Brain behavior relationships are networks, not a one-region answer for every experience.'],
['Sensation versus perception','Sensation begins when receptors detect physical energy, such as light or pressure. Transduction converts that energy into neural signals. Perception organizes and interprets those signals using context, expectations and previous experience. Bottom-up processing starts with incoming data; top-down processing applies existing knowledge. Selective attention prioritizes some information, so failing to notice a stimulus does not prove that the sense organ is damaged.'],
['Consciousness and regulation','The autonomic nervous system regulates involuntary functions. Sympathetic activation mobilizes resources during challenge, while parasympathetic activity supports restoration. Brainstem structures contribute to basic life functions; cortical networks support complex interpretation. Sleep is an active, organized state that supports attention and memory. Distinguish a description of a behavior from a hypothesis about the mechanism causing it.']
],case:'A learner hears an ambiguous word differently after reading a sentence that provides context. Their hearing test is normal.',explain:'The sound is the sensory input. The sentence changes top-down interpretation. The result illustrates perception and expectation, not proof of impaired hearing.',questions:[Q('Which process turns light into neural activity?','Transduction',['Retrieval','Reinforcement','Projection'],'Transduction converts stimulus energy into neural signaling.'),Q('Context changes the interpretation of an ambiguous sound. Which process best fits?','Top-down processing',['Loss of sensation','Operant punishment','Motor adaptation'],'Prior knowledge influences interpretation of sensory input.')],frq:'Explain the ambiguous-word example using sensation, perception and top-down processing.',criteria:[['Identify the sensory input',['sound','auditory','hearing']],['Explain interpretation',['perception','interpret']],['Connect expectations to context',['context','expectation','top-down']]],model:'The sound activates auditory receptors and pathways. Perception interprets the signal as a word. Sentence context creates an expectation that biases top-down interpretation, even when hearing is normal.'},
{title:'Learning, motivation and durable memory',points:[
['Classical and operant learning','Classical conditioning associates stimuli: a previously neutral cue can eventually evoke a learned response. Operant conditioning links behavior to consequences. Reinforcement increases a behavior; punishment decreases it. Positive means adding a stimulus and negative means removing one. Negative reinforcement therefore is not punishment. If fastening a seat belt stops an unpleasant alarm and increases fastening, removal of the alarm reinforces the behavior.'],
['Encoding, storage and retrieval','Encoding transforms experience into a usable representation, storage maintains information, and retrieval makes it available later. Working memory has limited capacity, so organizing information into meaningful chunks can reduce load. Retrieval practice and spaced review expose what is actually available without cues. Familiarity while rereading is weaker evidence of learning than explaining an idea from memory. Sleep and attention affect encoding and consolidation.'],
['Motivation and emotion','Intrinsic motivation comes from interest or satisfaction in the activity; extrinsic motivation involves outcomes such as rewards. Both can influence behavior, and their effects depend on context. Emotions include subjective experience, physiological activity and interpretation. An exam can produce arousal without implying a disorder. Evaluate duration, intensity and interference before confusing ordinary emotion with clinical impairment.']
],case:'A student repeatedly rereads a page and feels confident, but cannot explain it the next day. A second student closes the book, recalls the pathway, and corrects missing steps.',explain:'The second method tests retrieval and supplies targeted feedback. Spacing those attempts helps distinguish durable memory from short-term familiarity.',questions:[Q('A loud reminder stops when a task is completed, increasing completion. This is:','Negative reinforcement',['Positive punishment','Negative punishment','Extinction'],'Removing an unpleasant stimulus increases the behavior.'),Q('Which most directly tests retrieval?','Explain the concept with the book closed',['Highlight every sentence','Read the same paragraph continuously','Copy the answer while looking'],'Recall without visible cues tests whether the representation can be retrieved.')],frq:'Explain why the seat-belt alarm is negative reinforcement and design one retrieval-based study activity.',criteria:[['Behavior increases',['increase','more likely']],['A stimulus is removed',['remove','stops','alarm']],['Recall without cues',['recall','closed','without']]],model:'Fastening becomes more likely because the unpleasant alarm stops; a stimulus is removed, so this is negative reinforcement. Close the book, draw the memory pathway from recall, then compare it with the source and repeat after a delay.'}
]],
['Disorders and treatment pathways',[
{title:'Mood, anxiety, trauma and obsessive-compulsive conditions',points:[
['Recognize patterns without labeling people','Depressive disorders involve persistent mood or interest changes with associated symptoms and impairment. Bipolar disorders involve episodes of mania or hypomania, with depressive episodes occurring in many presentations. Mania is more than ordinary happiness: marked changes in energy, sleep, activity and judgment matter. A short vignette may illustrate a pattern but does not replace assessment, medical evaluation or a full history.'],
['Differentiate related mechanisms','Anxiety becomes clinically significant when excessive fear or worry causes distress or interferes with functioning. Panic attacks are episodes of intense fear and physical symptoms; an attack alone does not establish panic disorder. In obsessive-compulsive disorder, intrusive obsessions and repetitive compulsions can form a distress-relief cycle. PTSD follows qualifying trauma exposure and involves patterns such as intrusion, avoidance, negative mood or cognition changes and heightened arousal.'],
['Connect treatment to assessment','Psychotherapies use different mechanisms. Cognitive behavioral approaches examine relationships among thoughts, feelings and actions. Exposure-based approaches are structured treatments delivered with appropriate professional support. Medication decisions depend on diagnosis, individual risk, response and monitoring. Supportive communication describes observed changes and encourages assessment without insisting that someone has a particular condition.']
],case:'A person repeatedly checks a lock to reduce distress from an intrusive fear, but the relief is brief and checking consumes substantial time.',explain:'The intrusive fear and ritual illustrate an obsession-compulsion cycle. The immediate relief can reinforce checking. A trained clinician must evaluate the complete presentation.',questions:[Q('Which distinguishes a compulsion in this example?','Repetitive checking intended to reduce distress',['Any unpleasant thought','A single realistic safety check','An elevated mood episode'],'A compulsion is a repetitive behavior or mental act linked to distress reduction or rigid rules.'),Q('Which response is most appropriate for a student observer?','Describe changes and encourage professional assessment',['Give a definitive diagnosis','Recommend stopping a prescribed medication','Assume symptoms reflect poor character'],'Observation and referral respect uncertainty and scope.')],frq:'Explain the obsession-compulsion cycle and why a vignette is insufficient for diagnosis.',criteria:[['Intrusive thought',['intrusive','obsession','fear']],['Behavior briefly reduces distress',['checking','compulsion','relief']],['Assessment requires broader evidence',['assessment','history','clinician']]],model:'An intrusive fear produces distress, checking briefly reduces it, and that relief can maintain repeated checking. A clinician still needs duration, impairment, history and alternative explanations before diagnosing OCD.'},
{title:'Neurodevelopment, psychosis, personality and eating disorders',points:[
['Development and diversity','Autism involves patterns of social communication differences and restricted or repetitive behaviors or interests, with varied support needs. ADHD involves developmentally inappropriate patterns of inattention and/or hyperactivity-impulsivity that interfere with functioning. Neither label describes intelligence, worth or an entire personality. Developmental history and multiple settings help separate a persistent pattern from a temporary response to stress, sleep loss or an unfamiliar environment.'],
['Psychosis and dissociation','Psychosis can include hallucinations, delusions and disorganized thinking. Hallucinations are perceptual experiences without a corresponding external stimulus; delusions are fixed false beliefs not explained by cultural context. Psychosis can occur in several conditions and is not synonymous with dangerousness. Dissociation concerns disruptions in the integration of memory, identity, awareness or perception. It is distinct from the popular but inaccurate idea that schizophrenia means multiple personalities.'],
['Patterns, nutrition and person-centered care','Personality disorders concern enduring, inflexible patterns that cause impairment, assessed in developmental and cultural context. Eating disorders can involve restriction, binge eating, compensatory behaviors or other disturbances; serious illness can occur at many body sizes. Assessment includes medical and psychosocial concerns. Person-first or identity-first language should respect individual preference. Focus on access, dignity and functional needs rather than stereotypes.']
],case:'A patient reports hearing a voice that others cannot hear. Another describes feeling detached from their surroundings during stress.',explain:'The first describes a hallucination; the second describes a possible dissociative experience. Neither isolated symptom establishes a specific diagnosis.',questions:[Q('Which term means a perception without a corresponding external stimulus?','Hallucination',['Compulsion','Reinforcement','Circadian rhythm'],'Hallucinations are perceptual experiences without a matching external stimulus.'),Q('Which claim about eating disorders is accurate?','Medical severity cannot be inferred from appearance alone',['Only visibly underweight people can be affected','They are simply preferences','They never require medical assessment'],'Appearance does not establish nutritional or medical stability.')],frq:'Differentiate hallucination from dissociation and explain one person-centered assessment principle.',criteria:[['Perception without stimulus',['perception','stimulus','voice']],['Disrupted integration or detachment',['detachment','integration','dissociation']],['Respectful individualized assessment',['respect','individual','assessment']]],model:'A hallucination is a perception without an external stimulus. Dissociation involves disrupted integration or detachment from experience. Assessment should respect the person, consider context and functional impact, and avoid diagnosing from a single symptom.'}
]],
['Prevention, substance use and recovery',[
{title:'Substance use: risk, reinforcement and prevention',points:[
['Separate use, dependence and disorder','Substance-related problems are evaluated by patterns of impaired control, consequences and functioning. Tolerance means a reduced response to the same exposure; withdrawal is a syndrome following reduction or cessation after adaptation. Physical dependence can occur during appropriate prescribed treatment and is not, by itself, a substance use disorder. Avoid moral explanations that ignore biological, psychological and social influences.'],
['Risk and protective factors','Risk factors increase probability rather than guarantee an outcome. Examples include some patterns of exposure, stress and limited support. Protective factors such as connectedness, coping skills and access to care can reduce vulnerability. Universal prevention reaches a whole population; selective prevention focuses on higher-risk groups; indicated prevention responds to early signs. The target population determines which category fits, not whether a campaign feels important.'],
['Choose meaningful outcomes','A prevention program should define an intended change and measure it. Counting posters is an activity measure; changes in knowledge, help-seeking or harmful use are outcomes. Evaluation should consider unintended stigma and who was not reached. Reliable health information, supportive environments and access to evidence-based treatment work together. A single scare message is not a substitute for an evaluated prevention strategy.']
],case:'A school offers coping-skills education to all students and a separate support program for students with early substance-related problems.',explain:'The first is universal prevention; the second is indicated prevention. Compare changes in relevant behaviors and access to support, not just attendance.',questions:[Q('Tolerance refers to:','Reduced effect from the same exposure',['A guaranteed substance use disorder','Any prescription use','A moral failure'],'Tolerance reflects physiological adaptation and does not alone establish a disorder.'),Q('A program for an entire school is which prevention level?','Universal',['Indicated','Selective','Acute detoxification'],'Universal prevention is offered to the entire target population.')],frq:'Distinguish tolerance from substance use disorder and identify an outcome for a universal prevention program.',criteria:[['Adaptation',['tolerance','reduced','same']],['Disorder involves impairment or consequences',['impairment','consequences','control']],['Meaningful outcome',['help-seeking','behavior','knowledge','outcome']]],model:'Tolerance means the same exposure has less effect. A disorder requires a problematic pattern such as impaired control or significant consequences. A universal school program might measure improved help-seeking or reduced harmful behavior rather than only counting sessions.'},
{title:'Recovery, treatment engagement and integrated care',points:[
['Recovery is multidimensional','Recovery is an ongoing, individualized process involving health, purpose, support and a stable living environment. Goals can include meaningful roles and improved daily functioning as well as symptom change. A recurrence of symptoms is a reason to reassess supports and treatment, not proof that improvement is impossible. Language such as person with a substance use disorder avoids reducing someone to a condition.'],
['Engagement and shared decisions','Motivational interviewing uses collaborative conversation to explore ambivalence and elicit the person’s reasons for change. Open questions, affirmations, reflective listening and summaries help the professional understand values. It is not arguing until a person agrees. Shared decision-making combines evidence, clinical judgment and the person’s preferences. Medication, psychotherapy and peer support may complement one another; the appropriate combination depends on assessment.'],
['Coordinate across systems','Co-occurring mental and substance use conditions can complicate access when services are separated. Integrated care coordinates behavioral and physical healthcare, clarifies responsibilities and supports follow-up. Peer specialists contribute lived experience; psychiatrists, psychologists, counselors, social workers and other professionals have distinct training and roles. Privacy and consent requirements must be checked for the setting instead of assuming that all records can be shared freely.']
],case:'A person misses appointments because transportation is unreliable, but a team labels them unmotivated.',explain:'The team should explore practical barriers and the person’s priorities. Coordinated transportation support and follow-up may address the actual obstacle better than blame.',questions:[Q('Which question fits motivational interviewing?','What changes would matter most to you?',['Why will you not obey?','Would you admit you are wrong?','Can I decide your goals for you?'],'An open question invites the person’s values and reasons for change.'),Q('Integrated care primarily seeks to:','Coordinate related healthcare needs',['Replace every professional with one role','Eliminate consent requirements','Guarantee a single treatment works'],'Integration coordinates care while preserving roles and appropriate information handling.')],frq:'Propose a recovery-oriented response to missed appointments caused by transportation barriers.',criteria:[['Explore the barrier without blame',['transport','barrier','ask']],['Include personal goals',['goal','preference','person']],['Coordinate practical support',['coordinate','support','follow-up']]],model:'Ask about transportation and other barriers without blame, clarify the person’s goals and preferences, and coordinate practical support and follow-up. Track whether access improves instead of interpreting attendance alone as motivation.'}
]],
['Wellness, workforce and systems',[
{title:'Stress, coping and resilience',points:[
['Appraisal shapes stress','Stress involves demands and a person’s appraisal of available resources. The same event can be experienced differently depending on predictability, control, previous experience and support. Short-term arousal can support action; prolonged demands without recovery can disrupt sleep, concentration and health. Resilience is adaptive capacity supported by relationships and resources, not an obligation to tolerate harmful conditions alone.'],
['Match coping to the problem','Problem-focused coping addresses a modifiable stressor, such as planning a workload or seeking clarification. Emotion-focused coping changes the response to distress through supportive conversation, relaxation or reframing. These strategies can be combined. Avoidance may bring brief relief while leaving the underlying problem unchanged. Evaluate coping by its consequences and fit, rather than assuming every distraction is harmful or every emotional response is ineffective.'],
['Design a realistic wellness plan','A practical plan identifies the stressor, an achievable action, a source of support and a way to review progress. Sleep routines, movement, nutrition and connection support well-being, but do not replace indicated professional care. At an organizational level, staffing, workload and respectful culture matter. Burnout prevention should therefore include work conditions, not only individual wellness exercises.']
],case:'A student is anxious because three deadlines overlap. They ask an advisor to help prioritize and use a brief breathing exercise before starting.',explain:'Prioritizing addresses the task demands; breathing supports emotional regulation. The strategies work together rather than competing.',questions:[Q('Which is problem-focused coping?','Negotiating a clearer workload plan',['Ignoring every deadline','Assuming stress proves weakness','Only suppressing feelings'],'Planning changes a modifiable source of demand.'),Q('Which best describes resilience?','Adaptation supported by personal and environmental resources',['Never feeling distress','Handling every problem alone','Accepting unsafe conditions indefinitely'],'Resilience involves adaptation and support, not invulnerability.')],frq:'Create a plan combining problem-focused and emotion-focused coping for overlapping deadlines.',criteria:[['Change the demand',['prioritize','plan','deadline']],['Regulate distress',['breathing','emotion','relax']],['Use support and review',['support','advisor','review']]],model:'List and prioritize deadlines with an advisor, then schedule manageable work blocks. Use a brief breathing practice to regulate distress before starting. Review the plan with support and adjust if the workload remains unrealistic.'},
{title:'Professional roles, confidentiality and the evolution of care',points:[
['Know what a role contributes','Psychiatrists are physicians trained in mental healthcare; psychologists often focus on assessment and psychological interventions, with legal scope varying by jurisdiction. Counselors and clinical social workers provide services within their credentials and training. Peer support workers contribute lived experience and recovery support. In a test vignette, identify the function needed rather than assuming one profession performs every task.'],
['Confidentiality has a framework','Confidentiality supports trust, but disclosure rules depend on jurisdiction, setting, record type and circumstances. Appropriate information sharing follows applicable law and organizational procedures. Professionals explain limits during informed consent and consult designated supervisors when uncertain. Students should not promise absolute secrecy or access records merely out of curiosity. The least information needed for an authorized task is a useful privacy habit.'],
['Systems and historical change','Behavioral healthcare has shifted across institutional, community and integrated models. Moving care into the community creates benefits only when accessible housing, treatment and support actually exist. Stigma, workforce shortages and fragmented payment can interfere with access. Analyze a reform by the experience and outcomes of people receiving care: continuity, dignity, availability and recovery support matter more than the name of the model.']
],case:'A clinic adds a behavioral health professional to primary care but keeps separate referral queues and loses patients between appointments.',explain:'Physical proximity is not sufficient integration. A shared referral process, appropriate information exchange and explicit follow-up responsibilities can improve continuity.',questions:[Q('Which best protects privacy in a student placement?','Access records only for an authorized role',['Read interesting cases during breaks','Promise secrecy under all circumstances','Share cases with identifying details in a study group'],'Access requires a legitimate authorized purpose.'),Q('Which most directly improves continuity?','Assign responsibility for referral follow-up',['Place offices next to one another only','Create another disconnected queue','Assume patients will coordinate every handoff'],'Clear ownership prevents referrals from being lost between services.')],frq:'Explain why co-location alone is not integrated care and name a privacy safeguard.',criteria:[['Coordination beyond location',['coordinate','referral','handoff']],['Clear follow-up responsibility',['responsibility','follow-up','owner']],['Authorized information use',['privacy','authorized','consent']]],model:'Co-location does not ensure coordinated referrals or follow-up. Assign a team member to track the handoff and confirm access. Share information only through authorized processes consistent with consent and applicable privacy requirements.'}
]]
]);

course('Biomedical Equipment Technician',[
['Anatomy and device measurement',[
S('Physiology behind patient monitors',[
['Electrical versus mechanical activity','An ECG records differences in electrical potential at the skin. It does not directly measure cardiac output or prove that a pulse is present. Blood pressure reflects pressure within arteries; a cuff estimates it using a specific method. A pulse oximeter estimates peripheral oxygen saturation from light absorption and pulsatile blood flow. Each instrument measures a different aspect of physiology.'],
['Trace the signal chain','A sensor converts a physical quantity into an electrical signal. Conditioning, conversion, processing and display transform that signal into useful information. A loose connection, unsuitable sensor placement or movement can introduce artifact before the display. Start by asking what the device measures and where the signal may be distorted.'],
['Interpret limits','A displayed number is meaningful only with appropriate patient context and a valid measurement. Low perfusion, motion and sensor problems can impair readings. A technician verifies equipment performance using approved simulators and procedures, while clinical staff assess the patient. Never equate a successful simulator check with proof that a patient is clinically stable.']
],'An ECG trace appears normal while a separate pulse reading is absent. What can the ECG establish?','It establishes recorded electrical activity, not effective circulation. Clinical assessment and the measurement chain require separate attention.',[Q('What does ECG directly record?','Electrical potential differences',['Blood oxygen content','Cardiac output','Arterial pressure'],'ECG measures electrical activity.'),Q('Which belongs to equipment verification?','Use an approved patient simulator',['Diagnose from a monitor alone','Ignore sensor placement','Assume every alarm is a fault'],'A simulator supplies known inputs for a controlled performance check.')],'Explain why an ECG and a pulse oximeter cannot be treated as interchangeable measurements.',[['ECG signal',['electrical','potential']],['Oximetry measurement',['oxygen','saturation','light']],['Measurement limitation',['artifact','context','perfusion']]],'ECG records electrical potential differences; pulse oximetry estimates oxygen saturation using light and pulsatile flow. They measure different variables, and artifact or poor perfusion can affect interpretation.'),
S('Respiratory, infusion and imaging device functions',[
['Match technology to the system','A ventilator supports movement of gas according to configured modes; a capnograph measures carbon dioxide in exhaled gas. An infusion pump controls delivery of a fluid through a compatible set. These devices support different physiological functions. Know the intended use, inputs, outputs and alarm conditions before reasoning about a failure.'],
['Recognize imaging mechanisms','Radiography uses ionizing radiation to create an image based on attenuation. Ultrasound uses sound waves and their echoes. MRI uses strong magnetic fields and radiofrequency energy. These mechanisms create different hazards and access controls. An apparently familiar accessory must not be taken into an MRI environment without the required safety verification.'],
['Identify interfaces and consumables','Incorrect tubing, damaged cables, blocked filters or incompatible accessories can create failures even when internal electronics work. Manufacturer instructions specify approved combinations, cleaning and inspection. A functional check should evaluate the complete configured system rather than only whether the power light illuminates. Clinical settings must not be changed casually as a troubleshooting shortcut.']
],'A pump passes its electronic self-test but repeatedly alarms when one particular tubing set is installed.','Inspect compatibility and the fluid pathway using approved procedures. A passed self-test does not verify every accessory or operating condition.',[Q('Which imaging modality uses sound waves?','Ultrasound',['Radiography','CT','MRI'],'Ultrasound forms images from acoustic echoes.'),Q('What does a passed self-test prove?','Only the functions actually tested passed',['All accessories are compatible','All clinical settings are correct','No further inspection is needed'],'A test supports conclusions only about its scope.')],'Describe a safe reasoning path for a pump that alarms with one tubing set.',[['Accessory compatibility',['tubing','compatible','accessory']],['Bounded test result',['self-test','scope','tested']],['Approved verification',['manufacturer','procedure','verify']]],'Check the tubing and compatibility against manufacturer instructions. The self-test covers only its programmed checks. Verify the complete system through approved procedures and communicate findings before returning it to use.')
]],
['Electricity and healthcare safety',[
S('Voltage, current, resistance and power',[
['Use relationships with units','Voltage is electrical potential difference, current is charge flow, and resistance opposes that flow. For an ohmic element, V = I × R. Power can be calculated as P = V × I. Keep units visible: volts, amperes, ohms and watts describe different quantities. A current of 0.02 A is 20 mA, not 0.02 mA.'],
['Series and parallel paths','In a simple series circuit the same current passes through each component, and resistances add. Parallel branches share voltage while branch currents depend on resistance. An open path interrupts current; a short creates an unintended low-resistance path. Real medical devices include protective and complex electronic components, so textbook relationships do not authorize probing a live device.'],
['Measure safely','A voltmeter is placed across a potential difference; a current measurement requires an appropriate measurement arrangement and instrument rating. Electrical service follows authorized procedures, isolation requirements and suitable test equipment. Inspect damaged cords, protective earth connections and enclosures. Patient-connected equipment needs specialized safety testing rather than improvised household checks.']
],'A training resistor of 600 ohms has 12 V across it. Calculate current and power.','I = 12/600 = 0.02 A = 20 mA. P = 12 × 0.02 = 0.24 W. These are training-circuit calculations.',[Q('12 V across 600 ohms gives what current?','20 mA',['50 A','7200 A','0.02 mA'],'12/600 = 0.02 A, which equals 20 mA.'),Q('In a simple series path, which is shared?','Current',['Voltage across every unequal resistor','Resistance of each component','Power of every component'],'All charge passes through the same series path.')],'Show the current and power calculations and explain why these do not authorize live device repair.',[['Current with units',['0.02','20 ma']],['Power',['0.24','watt']],['Safety boundary',['authorized','procedure','live']]],'Current is 12/600 = 0.02 A, or 20 mA; power is 12 × 0.02 = 0.24 W. Actual device repair requires authorization, isolation and manufacturer procedures.'),
S('Infection control, electrical hazards and incident response',[
['Separate cleaning and disinfection','Cleaning removes soil and organic material. Disinfection reduces or inactivates microorganisms to a specified level; sterilization eliminates viable microorganisms including spores when properly performed. Equipment must be processed using manufacturer-compatible methods. An incompatible chemical can damage a sensor or enclosure even if it is effective against microbes.'],
['Control the hazard before testing','An exposed conductor, liquid intrusion, unusual heat or damaged enclosure can make continued use unsafe. Follow facility procedures to remove suspect equipment from service, identify it clearly and notify responsible staff. Protect the patient through clinical personnel and approved alternatives. Do not keep operating a suspect device merely to reproduce an error.'],
['Document useful evidence','Record the asset identifier, observed fault, operating conditions, accessories and actions taken. Preserve relevant logs and accessories according to incident procedures. Distinguish observations from guesses: “display blank after power-on” is more useful than “motherboard bad” without supporting tests. Accurate records support investigation, recurring-failure analysis and safe release decisions.']
],'A staff member reports a tingling sensation from a device with a damaged power cord.','Treat the report as a potential safety incident, remove the device from use through facility procedures and document the condition. Do not dismiss the report because the device still powers on.',[Q('Which must usually precede effective disinfection?','Cleaning',['Painting','Calibration','Network enrollment'],'Soil can interfere with disinfectant contact and effectiveness.'),Q('Which is an objective service note?','Cord insulation visibly split near plug',['Probably a careless user','Definitely a failed processor without testing','Safe because the display works'],'The note describes directly observed evidence.')],'Describe the first response and documentation for a damaged patient-care device.',[['Control exposure',['remove','isolate','service']],['Notify and protect',['notify','patient','staff']],['Record observations',['document','asset','cord']]],'Remove the device from service following facility procedures, notify clinical and technical staff, and support an approved alternative. Record the asset ID, damaged cord, reported sensation and actions without inventing a diagnosis.')
]],
['Reasoning and maintenance',[
S('Troubleshooting with hypotheses and evidence',[
['Define the fault precisely','Begin with the expected function and the observed deviation. Ask when the problem started, whether it is intermittent, which accessories are attached and what changed. Reproduce the condition only when safe and authorized. A vague complaint such as “does not work” should become a measurable statement about an output, control or alarm.'],
['Test one explanation at a time','Generate plausible causes across power, connections, settings, accessories, environment, network and internal components. Prioritize safe, informative checks. A controlled substitution can help isolate a faulty accessory, but only approved compatible components should be used. Changing multiple variables simultaneously makes it harder to determine which change mattered.'],
['Verify and close the loop','A repair is incomplete until the intended function and relevant safety checks pass. Compare results against manufacturer criteria, document the work and communicate release status. If a fault is not reproduced, record that limitation rather than declaring it imaginary. Trend repeated complaints to identify intermittent or system-level failures.']
],'A monitor intermittently loses its signal only when a particular cable is bent.','The association makes cable integrity a testable hypothesis. Approved substitution and inspection can isolate the cable; complete functional and safety verification is still needed.',[Q('Why change one variable at a time?','To identify which change affects the fault',['To avoid documenting results','To guarantee every fault is simple','To skip verification'],'Controlled changes preserve causal interpretability.'),Q('A fault is not reproduced. The best note is:','State the tests and the limitation',['No fault could ever exist','User fabricated the complaint','Repair complete without checks'],'Failure to reproduce is a bounded finding.')],'Create a hypothesis, controlled test and verification step for the cable scenario.',[['Hypothesis',['cable','intermittent']],['Controlled test',['substitute','one','approved']],['Post-test verification',['verify','functional','safety']]],'Suspect intermittent cable continuity. Test using an approved compatible cable while holding other conditions constant. Verify normal function and required safety checks, then document results and limitations.'),
S('Preventive maintenance, calibration and device lifecycle',[
['Understand the difference','Preventive maintenance consists of planned tasks intended to maintain function and reduce failure. Calibration compares measurement performance against a traceable reference and may include adjustment as specified. A device can be clean and functional yet outside measurement tolerance. Conversely, calibration alone does not establish that all alarms, batteries or mechanical parts work.'],
['Use risk and history','Maintenance schedules follow applicable requirements, manufacturer recommendations and the organization’s approved program. Risk considers the consequences of failure, probability, detectability and clinical use. Service history can reveal recurring failures or battery degradation. Inventory records connect asset identity, location, model, maintenance status and service documentation.'],
['Manage the whole lifecycle','Technology management includes selection, acceptance testing, deployment, training, maintenance, recalls and retirement. Before release, confirm configuration and staff readiness. Before disposal, address stored information and environmental requirements. Procurement decisions should consider serviceability, consumables, training and support costs rather than purchase price alone.']
],'Two thermometers power on, but one reads a reference source consistently high.','Power-on shows basic operation; comparison with the traceable reference identifies measurement error. Follow the calibration procedure and tolerance criteria.',[Q('What is calibration fundamentally based on?','Comparison with a suitable reference',['Whether the case looks clean','The age of the operator','Only a battery check'],'Calibration assesses measurement against a reference.'),Q('Which is a lifecycle cost?','Recurring compatible consumables',['Only the purchase price','The color of the enclosure','A one-time slogan'],'Consumables affect the long-term cost of ownership.')],'Distinguish calibration from preventive maintenance and explain one reason to track service history.',[['Reference comparison',['reference','calibration']],['Planned upkeep',['maintenance','planned']],['Trend failures',['history','trend','recurring']]],'Calibration compares measurements with a reference; preventive maintenance performs planned upkeep. Service history identifies recurring faults and supports decisions about maintenance, replacement and reliability.')
]],
['Healthcare IT and public safety',[
S('Networks, interoperability and connected-device security',[
['Follow the data path','A connected device may acquire data, label it with patient identity, transmit it through a network and deliver it to a clinical system. Addressing, connectivity, interface configuration and identity matching all matter. A device can operate locally while its results fail to reach the record. Troubleshooting should distinguish measurement failure from transmission failure.'],
['Protect confidentiality, integrity and availability','Confidentiality limits unauthorized access, integrity protects against improper alteration, and availability ensures authorized users can obtain needed functions. A cybersecurity event may affect safety when a device becomes unavailable or data are incorrect. Approved patching, access controls, asset inventory and network controls reduce risk. Unapproved software or improvised changes can create new hazards.'],
['Coordinate technical roles','BMETs, clinical users, IT and cybersecurity teams share responsibilities but have different expertise. Document device and network context, escalate appropriately, and follow downtime procedures. Never test security by disrupting clinical equipment without authorization. Updates require compatibility and operational planning because a technically successful installation may still alter clinical workflow.']
],'A device displays a reading correctly but the EHR receives it under the wrong patient.','The acquisition may be correct while identity association is wrong. Treat this as an integrity and patient-safety issue and escalate through approved processes.',[Q('Wrong patient association primarily threatens:','Data integrity and safety',['Screen brightness','Only device cosmetics','The laws of electricity'],'Accurate attribution is part of trustworthy data.'),Q('A local display works but transmission fails. First distinguish:','Acquisition from connectivity',['All users from all patients','Voltage from anatomy only','Purchase price from warranty'],'Separating functions narrows the fault domain.')],'Trace the connected-device data path and identify a safeguard against wrong-patient records.',[['Acquisition and transfer',['sensor','acquire','transmit']],['Identity association',['patient','identity','match']],['Controlled escalation',['verify','escalate','approved']]],'The sensor acquires data, the device associates patient identity, and an interface transmits results to the EHR. Verify identity mapping and escalate incorrect associations under approved procedures before further use.'),
S('Human factors, alarms and equipment safety communication',[
['Design for real users','Human factors examines how people, tasks, tools and environments interact. Confusing controls, similar connectors, interruptions or poorly designed labels can contribute to error. Asking who made a mistake is less informative than investigating conditions that made the mistake likely. Training helps, but it cannot compensate for every design problem.'],
['Interpret alarms as a system','An alarm combines sensing, thresholds, signal processing, annunciation and response. Excessive nonactionable alarms can reduce attention. Disabling alarms without authorization removes protection rather than solving the underlying issue. Clinical teams determine patient-specific settings; technicians verify alarm function and investigate device-related causes under their scope.'],
['Communicate actionable findings','A useful handoff states the device, observed problem, immediate action, test results, unresolved limitations and next responsible person. Plain language helps clinical staff understand whether equipment is released, restricted or out of service. Training should include demonstrations and checks of understanding, especially after new equipment or interface changes.']
],'A new pump menu makes two settings easy to confuse, and several units report the same error.','The repeated pattern suggests a system or interface problem. Collect evidence, involve safety and clinical teams, and consider design or workflow changes as well as education.',[Q('Repeated similar errors across users suggest examining:','System design and workflow',['Only individual motivation','Only the newest employee','Whether reporting should stop'],'Patterns across users may reveal shared conditions.'),Q('An effective equipment handoff includes:','Release status and unresolved limitations',['Only “fixed”','Only the technician’s name','A guess presented as certainty'],'Recipients need actionable status and remaining uncertainty.')],'Explain a system-focused response to repeated menu-selection errors.',[['Shared conditions',['design','interface','workflow']],['Evidence and collaboration',['collect','team','report']],['Improvement and verification',['change','verify','training']]],'Examine the interface and workflow, collect reports and involve technical, clinical and safety teams. Implement an approved change or training intervention, then verify whether errors decline without creating new problems.')
]]
]);

course('Dental Terminology',[
['Anatomy and the language of dentistry',[
S('Tooth tissues, surfaces and landmarks',[
['Name the structures','Enamel covers the anatomical crown; cementum covers the root. Dentin forms much of the tooth, surrounding the pulp space containing vessels, nerves and connective tissue. The periodontal ligament connects the root to alveolar bone. Distinguish a tissue from a space: pulp is living tissue, while the pulp chamber and root canal are spaces it occupies.'],
['Locate surfaces precisely','Mesial means toward the midline of the dental arch and distal means away from it. Facial surfaces face outward; labial is toward the lips and buccal toward the cheek. Lingual faces the tongue; palatal is used for the palate-facing surface of maxillary teeth. Posterior teeth have occlusal surfaces, while anterior teeth have incisal edges.'],
['Describe form and function','Cusps, ridges, grooves and fossae describe tooth morphology. A cusp is an elevation; a fossa is a depression. Anterior teeth cut or tear, and posterior teeth contribute to crushing and grinding. Use location and structure together rather than memorizing a word without a spatial relationship.']
],'A chart describes decay on the mesial surface of a molar.','The location is the side toward the arch midline, not necessarily the cheek side. Surface terminology allows precise communication without a drawing.',[Q('Which tissue covers the root?','Cementum',['Enamel','Pulp','Gingiva'],'Cementum covers the anatomical root.'),Q('Mesial means:','Toward the arch midline',['Toward the cheek','Away from the midline','Toward the root tip'],'Mesial is defined relative to the dental arch midline.')],'Describe enamel, dentin and pulp and locate the mesial surface.',[['Outer crown',['enamel','crown']],['Internal tissues',['dentin','pulp']],['Midline relationship',['mesial','midline']]],'Enamel covers the crown, dentin forms the bulk beneath it, and pulp contains vessels and nerves. The mesial surface faces toward the dental arch midline.'),
S('Head, neck, occlusion and specialty vocabulary',[
['Connect oral anatomy','The maxilla forms the upper jaw and the mandible the movable lower jaw. The temporomandibular joint permits mandibular movement. Salivary glands contribute lubrication, buffering and digestive components. The tongue, palate and muscles of mastication support swallowing and chewing. Anatomical terms describe structures; symptoms such as pain do not alone identify which structure is diseased.'],
['Describe occlusion','Occlusion concerns contact relationships between opposing teeth. Malocclusion describes abnormal alignment or relationships, but treatment decisions require individual assessment. Primary dentition is replaced during development by permanent teeth; mixed dentition includes both. Eruption refers to movement into the oral cavity, while exfoliation describes loss of primary teeth.'],
['Match specialties to scope','Orthodontics addresses alignment and occlusion; endodontics addresses pulp and related tissues; periodontics addresses supporting tissues; prosthodontics restores or replaces teeth. Oral and maxillofacial surgery includes surgical care of oral and facial structures. Pediatric dentistry focuses on children. Cosmetic descriptions concern appearance and should not be confused with a distinct disease process.']
],'A referral is made for disease involving the dental pulp, while another concerns loss of supporting bone.','Pulp-related care aligns with endodontics; supporting tissue disease aligns with periodontics. The specialty follows the tissues and clinical problem.',[Q('Which specialty focuses on pulp-related treatment?','Endodontics',['Orthodontics','Periodontics','Pediatric dentistry exclusively'],'Endodontics addresses the pulp and associated tissues.'),Q('Mixed dentition means:','Both primary and permanent teeth are present',['Only damaged teeth','A mixture of enamel and dentin','Only permanent molars'],'The term describes a developmental stage with both dentitions.')],'Compare endodontics, periodontics and orthodontics using their target tissues or relationships.',[['Pulp',['endodont','pulp']],['Supporting tissues',['periodont','support','bone']],['Alignment',['orthodont','alignment','occlusion']]],'Endodontics addresses pulp and related tissues, periodontics addresses supporting tissues such as gingiva and alveolar bone, and orthodontics addresses alignment and occlusion.')
]],
['Instruments, prevention and restorations',[
S('Instruments, examination and infection-control terms',[
['Identify function before appearance','A mouth mirror supports indirect vision and retraction. An explorer helps assess tooth surfaces, and a periodontal probe measures sulcus or pocket depth. Forceps grasp teeth for extraction; elevators assist loosening during procedures. Instruments with similar shapes can have different purposes, so learn the working end, task and associated terminology together.'],
['Distinguish deposits and prevention','Dental plaque is a biofilm; calculus is mineralized deposit. Scaling removes deposits with appropriate instruments. Prophylaxis refers to preventive care, while diagnosis and treatment depend on clinical findings. Gingivitis describes gingival inflammation; periodontitis includes destructive changes in supporting tissues. These words are not interchangeable descriptions of any bleeding gum.'],
['Process instruments correctly','Cleaning removes soil, disinfection reduces microorganisms, and sterilization eliminates viable microorganisms including spores when properly achieved. Packaging, indicators and storage are part of a processing system. A visible clean surface is not proof of sterility. Equipment and infection-control vocabulary should be learned as a sequence from contaminated use to safe reuse.']
],'An instrument has millimeter markings and is used to assess periodontal pocket depth.','The description identifies a periodontal probe. Its measuring function distinguishes it from an explorer used to assess surfaces.',[Q('Which measures periodontal pocket depth?','Periodontal probe',['Mouth mirror','Extraction forceps','Mixing spatula'],'The probe has calibrated markings.'),Q('Mineralized plaque is called:','Calculus',['Pulp','Dentin','Composite'],'Calculus is a mineralized deposit.')],'Explain probe versus explorer and distinguish cleaning from sterilization.',[['Measuring pocket depth',['probe','depth']],['Surface examination',['explorer','surface']],['Processing distinction',['soil','clean','spores','steril']]],'A probe measures sulcus or pocket depth; an explorer helps assess surfaces. Cleaning removes soil, while sterilization is a validated process intended to eliminate viable microorganisms including spores.'),
S('Restorative materials and replacement options',[
['Recognize restoration types','A direct restoration is placed and formed in the mouth; an indirect restoration is fabricated outside the mouth and then placed. An inlay fits within the cusps, an onlay covers one or more cusps, and a crown covers the prepared clinical crown. A veneer covers a selected surface, commonly facial. A bridge replaces missing teeth using supporting units.'],
['Connect material to properties','Composite resin can bond to tooth structure through a specified adhesive process. Glass ionomer materials have different bonding and fluoride-related characteristics. Ceramics, metals and resin materials differ in strength, appearance, handling and application. Terms such as curing, polymerization, etching and bonding describe specific processes, not synonyms for every stage of restoration.'],
['Understand implants and prostheses','A dental implant is placed in bone to support a prosthesis; an abutment connects components. A removable partial denture replaces some teeth, while a complete denture replaces an entire arch of missing teeth. Terminology must identify what is replacing a tooth, what provides support and whether the prosthesis is fixed or removable.']
],'A laboratory fabricates a restoration covering one cusp, then the clinician places it at a later visit.','This is an indirect restoration; cusp coverage is consistent with an onlay. Fabrication location and extent are separate descriptive features.',[Q('A restoration fabricated outside the mouth is:','Indirect',['Always temporary','Always removable','An extraction'],'Indirect describes the fabrication approach.'),Q('Which component commonly connects an implant to a restoration?','Abutment',['Pulp','Sulcus','Frenum'],'The abutment connects implant and prosthetic components.')],'Compare an inlay, onlay and crown by coverage.',[['Within cusps',['inlay','within']],['Cusp coverage',['onlay','cusp']],['Full crown coverage',['crown','cover']]],'An inlay lies within the cusps, an onlay covers one or more cusps, and a crown covers the prepared clinical crown. All require context about material and fabrication method.')
]],
['Imaging and laboratory language',[
S('Dental radiography and image interpretation terms',[
['Know the view','A bitewing image shows crowns and adjacent supporting bone in the selected area. A periapical image includes the tooth and surrounding region near the root apex. A panoramic image provides a broad view of jaws and related structures. View selection depends on the clinical question rather than a belief that a larger image is always better.'],
['Describe image appearance','Radiopaque structures attenuate more x-rays and appear lighter; radiolucent regions attenuate fewer and appear darker. These are imaging descriptions, not diagnoses. Enamel is more radiopaque than less mineralized tissues. Positioning errors can distort relationships or overlap contacts, limiting interpretation even when exposure is technically adequate.'],
['Respect radiation and scope','Radiographic imaging uses ionizing radiation and must be justified and optimized under professional protocols. Students studying terminology should know exposure, receptor, collimation and artifact without independently deciding clinical imaging. An image must be interpreted alongside history and examination by qualified professionals.']
],'A question asks for a view that includes a tooth and its root apex.','A periapical image is the relevant term. A bitewing chiefly emphasizes crowns and adjacent bone, so it does not answer the same anatomical question.',[Q('Which view includes the root apex?','Periapical',['Bitewing by definition','An intraoral photograph','A study cast'],'Periapical views include the tooth and periapical region.'),Q('Radiolucent areas generally appear:','Darker',['Whiter','Always red','Invisible in every image'],'Less attenuation produces darker regions on the usual display.')],'Explain periapical versus bitewing and radiopaque versus radiolucent.',[['Root apex',['periapical','apex']],['Crowns and adjacent bone',['bitewing','crown']],['Attenuation and appearance',['dark','light','attenuat']]],'A periapical includes the tooth and root apex; a bitewing emphasizes crowns and adjacent bone. Radiopaque structures attenuate more and appear lighter, while radiolucent regions appear darker.'),
S('Impressions, casts and laboratory procedures',[
['Negative and positive forms','An impression is a negative reproduction of oral structures. A cast is a positive reproduction produced from an impression or digital workflow. Impression trays hold material in position. Digital scanning records surface information, but accuracy still depends on technique, complete data and the application. Do not confuse the material that records a form with the model made from it.'],
['Understand working properties','Working time is the period available to manipulate a material; setting time concerns its transition toward the required set. Mixing ratios, temperature and technique can affect material behavior. Gypsum products are used for casts; elastomeric and other impression materials serve different purposes. Follow manufacturer instructions rather than treating materials as interchangeable.'],
['Relate laboratory steps','An articulator supports casts and simulates selected jaw relationships. A wax pattern, investment, casting or milling step may appear in different fabrication workflows. The workflow should preserve identification, accuracy and communication between clinical and laboratory teams. Errors in an impression can be faithfully reproduced in a cast and then in the final restoration.']
],'A bubble in an impression becomes a defect in a cast used for a restoration.','The error propagates through the workflow. Checking the source impression prevents later work from amplifying a defective record.',[Q('An impression is a:','Negative reproduction',['Positive cast','Permanent implant','Radiographic exposure'],'It records an inverse form of the structures.'),Q('Working time describes:','The period available for manipulation',['Only storage shelf life','Patient appointment duration','Sterilization exposure time'],'Working time is a material-handling property.')],'Explain how an impression defect can affect a cast and final restoration.',[['Negative record',['impression','negative']],['Positive reproduction',['cast','positive']],['Error propagation',['defect','error','restoration']]],'The impression is a negative record, and the cast is its positive reproduction. An impression defect can carry into the cast and affect the fit or form of a restoration, so quality checks are needed before fabrication.')
]],
['Pain, emergencies and integrated vocabulary',[
S('Pharmacology and pain-management terminology',[
['Separate effects','An analgesic reduces pain. A local anesthetic produces loss of sensation in a targeted area; sedation reduces anxiety or awareness to a degree depending on depth. These effects are not identical. General anesthesia involves a deeper state with additional monitoring and airway considerations. Terminology questions often test these distinctions rather than drug doses.'],
['Describe administration and response','Topical means applied to a surface; infiltration and nerve block describe approaches to local anesthetic delivery. Onset, duration, indication, contraindication and adverse effect are distinct concepts. An allergy involves an immune mechanism and should not be used casually as a synonym for any unpleasant drug response. Accurate history and documentation guide clinical decisions.'],
['Connect pain to anatomy','Pulpal, periodontal and referred pain involve different possible sources. The intensity or location reported by a patient does not alone establish the cause. Dental professionals evaluate history, examination and appropriate tests. Learn terms such as inflammation, edema and paresthesia with definitions so that descriptions remain precise.']
],'A patient reports numbness after a local anesthetic and another reports nausea after medication.','Numbness may be an intended anesthetic effect; nausea is an adverse symptom and is not automatically evidence of allergy. Clinical assessment determines significance.',[Q('An analgesic primarily:','Reduces pain',['Replaces a missing tooth','Creates a radiograph','Always causes unconsciousness'],'Analgesia means pain relief.'),Q('Which is not automatically an allergy?','Nausea after a medication',['A documented immune-mediated reaction','A confirmed allergic response','A clinician-established hypersensitivity'],'An adverse effect can occur without an immune allergy.')],'Differentiate analgesia, local anesthesia and sedation.',[['Pain relief',['analges','pain']],['Localized sensation loss',['local','sensation','numb']],['Reduced awareness or anxiety',['sedation','anxiety','awareness']]],'Analgesia reduces pain, local anesthesia blocks sensation in a targeted region, and sedation alters anxiety or awareness. These effects overlap in some care plans but are distinct concepts.'),
S('Emergency terminology and comprehensive case decoding',[
['Recognize emergency vocabulary','Syncope is a transient loss of consciousness related to reduced cerebral perfusion. Dyspnea means difficult or uncomfortable breathing. Anaphylaxis is a serious systemic allergic reaction. Hypoglycemia refers to low blood glucose. Learning a term does not qualify a student to diagnose or treat a real emergency; follow the trained team and emergency procedures.'],
['Decode the entire statement','A phrase such as “periapical radiolucency of a mandibular molar” combines location, appearance, jaw and tooth type. Translate each component separately before combining them. It describes a finding and does not by itself establish a definitive diagnosis. This approach prevents a familiar word from overriding qualifiers elsewhere in the question.'],
['Practice exact spelling','The Dental Terminology guideline includes fill-in tiebreakers requiring correct spelling. Practice producing terms from definitions, not merely recognizing them. Compare periodontitis with pulpitis, radiopaque with radiolucent, and maxillary with mandibular. Build a correction log identifying whether errors came from meaning, location or letter sequence.']
],'Translate “periapical radiolucency of a mandibular molar” without assigning a diagnosis.','It describes a darker radiographic area near the root apex of a lower-jaw posterior tooth. The description needs clinical interpretation.',[Q('Dyspnea means:','Difficulty breathing',['Difficulty spelling','A tooth eruption','Loss of enamel'],'Dyspnea describes breathing discomfort or difficulty.'),Q('Mandibular refers to the:','Lower jaw',['Upper jaw','Tongue alone','Palate alone'],'The mandible is the lower jaw.')],'Translate the imaging phrase and explain why a description is not a diagnosis.',[['Location',['apex','root','periapical']],['Appearance and jaw',['dark','lower','mandib']],['Clinical interpretation',['assessment','diagnosis','context']]],'The phrase describes a dark area near a molar root apex in the lower jaw. It states location and imaging appearance; history, examination and professional interpretation are needed to determine the cause.')
]]
]);
